#pragma once

/// @file MockHosterServer.h
/// @brief Loopback file hoster for speed tests: /file/<name> redirects to /dl/<name> like a
/// hoster's download button, /dl/<name> streams generated bytes (Range, HEAD, keep-alive).
/// Runs on its own thread with its own event loop, so the code under test never slows it.

#include <QByteArray>
#include <QHash>
#include <QHostAddress>
#include <QRandomGenerator>
#include <QSemaphore>
#include <QTcpServer>
#include <QTcpSocket>
#include <QThread>
#include <QUrl>

#include <algorithm>
#include <atomic>
#include <cstring>
#include <memory>

class MockHosterServer : public QThread {
public:
    /// @p size bytes behind every /dl/<name>
    explicit MockHosterServer(qint64 size)
        : m_size(size)
    {
        // 1 MiB of noise; block k is the noise with k in its first 8 bytes (no two blocks alike)
        m_noise.resize(kBlock);
        QRandomGenerator rng(4711);
        rng.fillRange(reinterpret_cast<quint32*>(m_noise.data()), kBlock / 4);
        start();
        m_ready.acquire();
    }

    ~MockHosterServer() override
    {
        quit();
        wait();
    }

    [[nodiscard]] quint16 port() const { return m_port; }
    [[nodiscard]] qint64 size() const { return m_size; }
    /// The hoster page of @p name: redirects to the file
    [[nodiscard]] QString url(const QString& name) const
    {
        return QStringLiteral("http://127.0.0.1:%1/file/%2").arg(m_port).arg(name);
    }
    [[nodiscard]] int requests() const { return m_requests.load(); }
    [[nodiscard]] qint64 bytesSent() const { return m_sent.load(); }

    /// The bytes of the file from @p offset into @p out (@p len bytes).
    void fill(char* out, qint64 offset, qint64 len) const
    {
        while (len > 0) {
            const qint64 block = offset / kBlock;
            const qint64 in = offset % kBlock;
            const qint64 n = std::min(len, kBlock - in);
            std::memcpy(out, m_noise.constData() + in, size_t(n));
            // the block number over the first 8 bytes of each block
            for (qint64 i = in; i < 8 && i < in + n; ++i)
                out[i - in] = char((quint64(block) >> (8 * i)) & 0xff);
            out += n;
            offset += n;
            len -= n;
        }
    }

protected:
    void run() override
    {
        QTcpServer server;
        server.listen(QHostAddress::LocalHost, 0);
        m_port = server.serverPort();
        QObject::connect(&server, &QTcpServer::newConnection, &server, [this, &server] {
            while (QTcpSocket* s = server.nextPendingConnection())
                accept(s);
        });
        m_ready.release();
        exec();
    }

private:
    static constexpr qint64 kBlock = 1024 * 1024;
    static constexpr qint64 kQueued = 4 * kBlock;   ///< kept in the socket's buffer

    struct Conn {
        QByteArray in;
        qint64 next = 0;   ///< next byte of the file to send
        qint64 end = 0;    ///< one past the last
        bool close = false;
    };

    void accept(QTcpSocket* s)
    {
        auto conn = std::make_shared<Conn>();
        QObject::connect(s, &QTcpSocket::readyRead, s, [this, s, conn] {
            conn->in += s->readAll();
            serve(s, *conn);
        });
        QObject::connect(s, &QTcpSocket::bytesWritten, s, [this, s, conn] { pump(s, *conn); });
        QObject::connect(s, &QTcpSocket::disconnected, s, &QObject::deleteLater);
    }

    /// Answers the next request once its headers are in and the last body is out.
    void serve(QTcpSocket* s, Conn& c)
    {
        if (c.next < c.end)
            return;
        const qsizetype eoh = c.in.indexOf("\r\n\r\n");
        if (eoh < 0)
            return;
        const QByteArray head = c.in.left(eoh);
        c.in.remove(0, eoh + 4);
        ++m_requests;
        const QList<QByteArray> lines = head.split('\n');
        const QList<QByteArray> first = lines.value(0).trimmed().split(' ');
        const QByteArray method = first.value(0);
        const QByteArray path = first.value(1);
        QByteArray range;
        c.close = false;
        for (const QByteArray& l : lines) {
            const QByteArray low = l.trimmed().toLower();
            if (low.startsWith("range:"))
                range = low.mid(6).trimmed();
            else if (low == "connection: close")
                c.close = true;
        }
        QByteArray out;
        if (path.startsWith("/file/")) {
            out = "HTTP/1.1 302 Found\r\nLocation: /dl/" + path.mid(6) + "\r\nContent-Length: 0\r\n";
            c.next = c.end = 0;
        } else if (path.startsWith("/dl/")) {
            qint64 from = 0;
            qint64 to = m_size - 1;
            if (range.startsWith("bytes=")) {
                const QList<QByteArray> r = range.mid(6).split('-');
                from = r.value(0).toLongLong();
                if (!r.value(1).isEmpty())
                    to = std::min(to, r.value(1).toLongLong());
            }
            if (from > to) {
                out = "HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */" + QByteArray::number(m_size)
                      + "\r\nContent-Length: 0\r\n";
                c.next = c.end = 0;
            } else {
                out = range.isEmpty() ? "HTTP/1.1 200 OK\r\n" : "HTTP/1.1 206 Partial Content\r\n";
                if (!range.isEmpty())
                    out += "Content-Range: bytes " + QByteArray::number(from) + '-' + QByteArray::number(to) + '/'
                           + QByteArray::number(m_size) + "\r\n";
                out += "Content-Type: application/octet-stream\r\nAccept-Ranges: bytes\r\n"
                       "Content-Disposition: attachment; filename=\""
                       + path.mid(4) + "\"\r\nContent-Length: " + QByteArray::number(to - from + 1) + "\r\n";
                c.next = method == "HEAD" ? 0 : from;
                c.end = method == "HEAD" ? 0 : to + 1;
            }
        } else {
            out = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n";
            c.next = c.end = 0;
        }
        out += c.close ? "Connection: close\r\n\r\n" : "Connection: keep-alive\r\n\r\n";
        s->write(out);
        pump(s, c);
    }

    /// Tops the socket's buffer up with file bytes; then the next request.
    void pump(QTcpSocket* s, Conn& c)
    {
        while (c.next < c.end && s->bytesToWrite() < kQueued) {
            const qint64 n = std::min(kBlock, c.end - c.next);
            QByteArray b(n, Qt::Uninitialized);
            fill(b.data(), c.next, n);
            s->write(b);
            c.next += n;
            m_sent += n;
        }
        if (c.next < c.end || s->bytesToWrite() > 0)
            return;
        if (c.close)
            s->disconnectFromHost();
        else if (!c.in.isEmpty())
            serve(s, c);
    }

    const qint64 m_size;
    QByteArray m_noise;
    QSemaphore m_ready;
    quint16 m_port = 0;
    std::atomic<int> m_requests{0};
    std::atomic<qint64> m_sent{0};
};
